```



![cube in monogame](/uploads/course-lectures/2016e07954918c47e0a1c6b330736eba94766fee.png)



При использовании индексов при отрисовки TriangleList нам надо учитывать порядок индексов при отрсиовки отдельного треугольника - вершины должны идти по часовой стрелке. Например, один из треугольников задней поверхности имеет индексы 6,5,4, так как при повороте к нам вершины будут идти именно в этом порядке, если мы их будет смотреть по часовой стрелке. Если мы изменим порядок индексов, то мы можем получить нежелательный эффект - видимая часть будет обращена внутрь куда, а не наружу, как сейчас. И в этом случае следствие backface culling мы не увидим вообще этот треугольник даже при повороте к нам.

Также, как и в обычной двухмерной игре, в трехмерной сцене мы также можем использовать текстуры. Только теперь наша задача будет состоять в том, чтобы совместить вершины текстуры с вершинами треугольника.

Вершины текстуры имеют следующие условные координаты:

![texture coordinates in monogame](/uploads/course-lectures/2a5496abf0e7cc4789382e89990cbdaa709c5d68.jpg)

То есть верхний левый угол текстуры будет иметь условно координаты (0,0), а правый нижний угол - (1,1). Точка в середине текстуры соответственно имеет координату (0.5,0.5). Таким образом, манипулируя координатами от 0.0 до 1.0 мы можем получить любую точку текстуры.

И если у нас треугольники строятся по следующим четырем точкам пространства (-1,1,1), (1,1,1), (1,-1,1) и (-1,-1,1), то мы получим примерно следующее наложение текстуры на поверхности треугольников:

![texture mapping in monogame](/uploads/course-lectures/ac1ee45c9c584a59d6c54b009581e71ea56cee85.png)

Теперь применим наложение текстуры в программе:

```c#
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using Microsoft.Xna.Framework.Input;

namespace First3DGame
{
    public class Game1 : Game
    {
        GraphicsDeviceManager graphics;
        SpriteBatch spriteBatch;

        Matrix projectionMatrix;
        Matrix viewMatrix;
        Matrix worldMatrix;

        VertexBuffer vertexBuffer;
        IndexBuffer indexBuffer;

        BasicEffect effect;

        VertexPositionTexture[] verts;

        short[] textureIndices =
        {
                0,1,2, // передняя сторона
    			2,3,0,

                6,5,4, // задняя сторона
    			4,7,6,

                4,0,3, // левый бок
    			3,7,4,

                1,5,6, // правый бок
    			6,2,1,

                4,5,1, // вверх
    			1,0,4,

                3,2,6, // низ
    			6,7,3,
         };

        Texture2D texture;

        public Game1()
        {
            graphics = new GraphicsDeviceManager(this);
            Content.RootDirectory = "Content";
        }

        protected override void Initialize()
        {
            viewMatrix = Matrix.CreateLookAt(new Vector3(0, 0, 6), Vector3.Zero, Vector3.Up);

            projectionMatrix = Matrix.CreatePerspectiveFieldOfView(MathHelper.PiOver4,
                (float)Window.ClientBounds.Width / (float)Window.ClientBounds.Height,
                1, 100);

            worldMatrix = Matrix.CreateWorld(new Vector3(0f, 0f, 0f), new Vector3(0, 0, -1), Vector3.Up);

            verts = new VertexPositionTexture[8];
            verts[0] = new VertexPositionTexture(new Vector3(-1, 1, 1), new Vector2(0, 0));
            verts[1] = new VertexPositionTexture(new Vector3(1, 1, 1), new Vector2(1, 0));
            verts[2] = new VertexPositionTexture(new Vector3(1, -1, 1), new Vector2(1, 1));
            verts[3] = new VertexPositionTexture(new Vector3(-1, -1, 1), new Vector2(0, 1));
            verts[4] = new VertexPositionTexture(new Vector3(-1, 1, -1), new Vector2(0, 0));
            verts[5] = new VertexPositionTexture(new Vector3(1, 1, -1), new Vector2(1, 0));
            verts[6] = new VertexPositionTexture(new Vector3(1, -1, -1), new Vector2(1, 1));
            verts[7] = new VertexPositionTexture(new Vector3(-1, -1, -1), new Vector2(0, 1));

            vertexBuffer = new VertexBuffer(GraphicsDevice, typeof(VertexPositionTexture),
                 verts.Length, BufferUsage.None);
            vertexBuffer.SetData(verts);

            effect = new BasicEffect(GraphicsDevice);

            indexBuffer = new IndexBuffer(graphics.GraphicsDevice, typeof(short), 36, BufferUsage.None);
            indexBuffer.SetData<short>(textureIndices);

            base.Initialize();
        }

        protected override void LoadContent()
        {
            spriteBatch = new SpriteBatch(GraphicsDevice);
            texture = Content.Load<Texture2D>("stone");
            effect.TextureEnabled = true;
            effect.Texture = texture;
        }

        protected override void UnloadContent()
        { }

        protected override void Update(GameTime gameTime)
        {
            if (GamePad.GetState(PlayerIndex.One).Buttons.Back == ButtonState.Pressed || 
                Keyboard.GetState().IsKeyDown(Keys.Escape))
                Exit();

            if (Keyboard.GetState().IsKeyDown(Keys.Up))
            {
                worldMatrix *= Matrix.CreateRotationX(MathHelper.ToRadians(1));
            }
            if (Keyboard.GetState().IsKeyDown(Keys.Down))
            {
                worldMatrix *= Matrix.CreateRotationX(-1 * MathHelper.ToRadians(1));
            }
            if (Keyboard.GetState().IsKeyDown(Keys.Left))
            {
                worldMatrix *= Matrix.CreateRotationY(MathHelper.ToRadians(1));
            }
            if (Keyboard.GetState().IsKeyDown(Keys.Right))
            {
                worldMatrix *= Matrix.CreateRotationY(-1 * MathHelper.ToRadians(1));
            }

            base.Update(gameTime);
        }

        protected override void Draw(GameTime gameTime)
        {
            GraphicsDevice.Clear(Color.CornflowerBlue);

            effect.World = worldMatrix;
            effect.View = viewMatrix;
            effect.Projection = projectionMatrix;

            GraphicsDevice.SetVertexBuffer(vertexBuffer);
            GraphicsDevice.Indices = indexBuffer;

            foreach (EffectPass pass in effect.CurrentTechnique.Passes)
            {
                pass.Apply();
                GraphicsDevice.DrawUserIndexedPrimitives<VertexPositionTexture>(PrimitiveType.TriangleList, verts, 0, 8, textureIndices, 0, 12);
            }

            base.Draw(gameTime);
        }
    }
}
```

Чтобы выполнить маппинг текстуры на поверхность трехмерного объекта, применяются объекты типа **VertexPositionTexture**, которые принимают трехмерный вектор - координаты точки пространства и двухмерный вектор - координата текстуры.

Далее в методе `LoadContent()` загружается нужная текстура и настраивается эффект:

```c#
texture = Content.Load<Texture2D>("stone");
effect.TextureEnabled = true;
effect.Texture = texture;
```

В методе `Draw()` происходит отрисовка:

```c#
GraphicsDevice.DrawUserIndexedPrimitives<VertexPositionTexture>
	(PrimitiveType.TriangleList, verts, 0, 8, textureIndices, 0, 12);
```

И в результате мы получим текстурированный куб:

![текстурированный куб в monogame](/uploads/course-lectures/502d1998ca077aedd4a6cc24a819eb6ec7d41b03.png)

Правда, в отличие от простого создания куба, как было показано в прошлой теме, здесь нам надо гораздо больше вершин, чтобы получить полностью текстурированный куб. Так как в данном случае оттекстурированы должным образом только четыре треугольника, которые составляют лицевую и заднюю сторону куба.

Треугольники, линии, текстуры - это конечно все хорошо, но в реальности в большинстве случаев для создания трехмерных объектов будут использоваться модели.

Для загрузки 3D-моделей MonoGame использует специальную библиотеку Assimp. Наиболее распространенными форматами моделей являются FBX и COLLADA(dae). Также могут использоваться такие форматы как X и OBJ. Для создания моделей применяются специальные программы, например, Blender, и после создания модель экспортируется в проект.

Итак, создадим новый проект. И прежде всего добавим опять же с помощью Content.mgcb в качестве ресурса имеющуюся у нас модель. В принципе сейчас не проблема найти бесплатные 3d модели в различных форматах, либо создать свою с помощью специализированных инструментов, таких как Blender.

Если модель имеет зависимость от текстуры, то нам соответственно надо добавить файл модели и все файлы используемых текстур:

![3d модели в monogame](/uploads/course-lectures/cd78ec9fa910d8651a59caac74f4a766bef325ef.png)

В данном случае я добавил файл модели Rock4.dae - модель в формате COLLADA, также файл Rock-Texture-Surface.jpg, который используется для текстурирования модели.

И после добавления модели определим код приложения:

```c#
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using Microsoft.Xna.Framework.Input;

namespace _3DModelingApp
{
    public class Game1 : Game
    {
        GraphicsDeviceManager graphics;
        SpriteBatch spriteBatch;

        Matrix projectionMatrix;
        Matrix viewMatrix;
        Matrix worldMatrix;

        Model model; // переменная для хранения модели

        public Game1()
        {
            graphics = new GraphicsDeviceManager(this);
            Content.RootDirectory = "Content";
        }

        protected override void Initialize()
        {
            viewMatrix = Matrix.CreateLookAt(new Vector3(0, 0, 6), new Vector3(0, 0, 0), Vector3.Up);

            projectionMatrix = Matrix.CreatePerspectiveFieldOfView(MathHelper.PiOver4,
                (float)Window.ClientBounds.Width / (float)Window.ClientBounds.Height,
                1, 100);

            worldMatrix = Matrix.CreateWorld(new Vector3(0f, 0f, 0f), new Vector3(0, 0, -1), Vector3.Up);

            base.Initialize();
        }

        protected override void LoadContent()
        {
            spriteBatch = new SpriteBatch(GraphicsDevice);

            model = Content.Load<Model>("Rock4");
        }

        protected override void UnloadContent()
        {
        }

        protected override void Update(GameTime gameTime)
        {
            if (GamePad.GetState(PlayerIndex.One).Buttons.Back == ButtonState.Pressed || Keyboard.GetState().IsKeyDown(Keys.Escape))
                Exit();

            if (Keyboard.GetState().IsKeyDown(Keys.Up))
            {
                worldMatrix *= Matrix.CreateRotationX(MathHelper.ToRadians(1));
            }
            if (Keyboard.GetState().IsKeyDown(Keys.Down))
            {
                worldMatrix *= Matrix.CreateRotationX(-1 * MathHelper.ToRadians(1));
            }
            if (Keyboard.GetState().IsKeyDown(Keys.Left))
            {
                worldMatrix *= Matrix.CreateRotationY(MathHelper.ToRadians(1));
            }
            if (Keyboard.GetState().IsKeyDown(Keys.Right))
            {
                worldMatrix *= Matrix.CreateRotationY(-1 * MathHelper.ToRadians(1));
            }
            base.Update(gameTime);
        }

        protected override void Draw(GameTime gameTime)
        {
            GraphicsDevice.Clear(Color.CornflowerBlue);

            foreach (ModelMesh mesh in model.Meshes)
            {
                foreach (BasicEffect effect in mesh.Effects)
                {
                    effect.View = viewMatrix;
                    effect.World = worldMatrix;
                    effect.Projection = projectionMatrix;
                }
                mesh.Draw();
            }
            base.Draw(gameTime);
        }
    }
}
```

В результате на экране модель будет выглядеть примерно следующим образом:

![3d models in monogame](/uploads/course-lectures/5353f4b9edbce5da4ce16dee156b1c7b620687c1.png)

Для начала нам надо загрузить модель, которая будет представлять объект **Model**:

```c#
model = Content.Load<Model>("Rock4");
```

Также здесь передаем название файла модели без расширения. Файл текстуры загружать не надо.

Несмотря на то, что в данном случае используется одна модель, представляющая камень или кусок скалы, но на самом деле трехмерная модель представляет сложный объект, который может состоять из множества более мелких частей или мэшей (mesh).

Все мэши представляют объекты **ModelMesh**, которые в классе Model доступны в виде коллекции в свойстве `Meshes`.

Каждый мэш может содержать материалы и цвета, текстуры - все, что используется для отрисовке данного мэша. Мэш необязательно должен быть покрыт только одним цветом или текстурой; мы можем использовать для одного мэша несколько различных материалов. И в данном случае мы пробегаемся по всем эффектам мэша, которые представляют объект `BasicEffect`, устанавливаем матрицы, и затем вызываем метод `mesh.Draw()` для отрисовки мэша:

```c#
foreach (ModelMesh mesh in model.Meshes)
{
    foreach (BasicEffect effect in mesh.Effects)
    {
        effect.View = viewMatrix;
        effect.World = worldMatrix;
        effect.Projection = projectionMatrix;
    }
    mesh.Draw();
}
```
